    /**
     * Tests getting all MRPRuns.
     *
     * @return    Collection
     */
    public List<MRPRun> testGetAll() throws Throwable {
    LOGGER.info( "MRPRunTest:testGetAll() - Retrieving Collection of MRPRuns:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all MRPRun : " );
    List<MRPRun> collection  = null;

    try {
        // call the static get method on the MRPRunService
        collection = service.getAllMRPRun();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            MRPRun currEntity  = null;
            Iterator<MRPRun> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getMRPRunId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

